import { injectable } from 'inversify';

import { ARCADE_THEME, IOperatorTheme, TEAL_THEME } from '@game-studio/operator-theme';

import { queryStringParams } from '../services/query-string';
import { isInternationalBuild } from '../services/utilities';
import { IArcadeOperatorTheme, IOperatorDescription, OperatorList } from '../types';

const OPERATOR_DESCRIPTION_MAP: Record<OperatorList, IOperatorDescription> = {
    tombola: {
        theme: {
            ...TEAL_THEME,
            fontName: { regular: 'Wallop', bold: 'Wallop-Bold' }
        }
    },
    'tombola-arcade': {
        theme: {
            ...ARCADE_THEME,
            fontName: { regular: 'Wallop', bold: 'Wallop-Bold' }
        }
    }
};

@injectable()
export class OperatorModel {
    private operatorName: string;
    private operatorTheme: IArcadeOperatorTheme;

    public get name(): string { return this.operatorName; }
    public get theme(): IArcadeOperatorTheme { return this.operatorTheme; }

    public get baseTheme(): IOperatorTheme {
        return {
            ...this.theme,
            fontName: this.theme.fontName.regular
        };
    }

    public constructor() {
        this.setupOperator();
    }

    public forceTombolaOperator(): void {
        this.operatorName = 'tombola';
        this.operatorTheme = {
            ...this.operatorTheme,
            darkAccent: TEAL_THEME.darkAccent,
            midAccent: TEAL_THEME.midAccent,
            lightAccent: TEAL_THEME.lightAccent,
            veryLightAccent: TEAL_THEME.veryLightAccent,
            textColour: TEAL_THEME.textColour,
            primaryButton: TEAL_THEME.primaryButton,
            secondaryButton: TEAL_THEME.secondaryButton,
            tertiaryButton: TEAL_THEME.tertiaryButton,
            crossButton: TEAL_THEME.crossButton
        };
    }

    private setupOperator(): void {
        // International unauth demos only exists for IT atm
        // they should use the tombola theme, so fall back to the tombola operator
        const isInternationalUnAuthDemo = isInternationalBuild() && queryStringParams.isUnAuthDemoMode;
        const operatorName = queryStringParams.launchedFrom === 'arcade' && !isInternationalUnAuthDemo ? 'tombola-arcade' : 'tombola';
        const operatorDescription = OPERATOR_DESCRIPTION_MAP[operatorName];

        this.operatorName = operatorName;
        this.operatorTheme = operatorDescription.theme;
    }
}